-- Safe to re-run. Grade A/B cells are NOT overwritten.

-- 1. regional_cells (non-US sub-national rows)
UPDATE regional_cells
SET cost_stack = jsonb_build_object(
  'rent_occupancy',         ROUND(rev_p50 * 0.05),
  'payroll_total',          ROUND(rev_p50 * 0.16),
  'cost_of_goods_sold',     ROUND(rev_p50 * 0.72),
  'utilities',              ROUND(rev_p50 * 0.02),
  'marketing_acquisition',  ROUND(rev_p50 * 0.01),
  'insurance_professional', ROUND(rev_p50 * 0.01),
  'equipment_maintenance',  ROUND(rev_p50 * 0.02),
  'regulatory_licensing',   ROUND(rev_p50 * 0.01),
  'refreshed_at',           '2026-05-24',
  'source_note',            'FMI The Food Industry Speaks 2024 + NACS Annual Survey 2024. Country revenue captures local price level implicitly.',
  'grade',                  'C'
)
WHERE industry_id = 'grocery_stores'
  AND rev_p50 IS NOT NULL
  AND rev_p50 > 0
  AND (cost_stack IS NULL OR cost_stack->>'grade' IN ('C', 'D'));

